/// <summary>
/// MPJ_28395_Stock reservation - 25/07/2022
/// Class <c>METSalesOrderAutoReserveController</c> to auto reserve the sales order quantity.
/// </summary>
class METSalesOrderAutoReserveController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Creates new instance of <c>METSalesOrderAutoReserveController</c>
/// </summary>
protected void new()
{
    super();
 
    this.parmClassName(classStr(METSalesOrderAutoReserveService));
    this.parmMethodName(methodStr(METSalesOrderAutoReserveService, processOperation));
 
    this.parmDialogCaption("@MET:AutoStockReservation");
}

/// <summary>
/// Sets the caption of the job
/// </summary>
/// <returns>Caption of the job</returns>
public ClassDescription caption()
{
    return "@MET:AutoStockReservation";
}

/// <summary>
/// Method which is run while calling the corresponding menu item
/// </summary>
/// <param name = "args">Arguments passed from the menu item</param>
public static void main(Args args)
{
    METSalesOrderAutoReserveController controller;
 
    controller = new METSalesOrderAutoReserveController();
    controller.startOperation();
}
